  /** HTTP resources referenced by a final HTTPS document. */
  mixedContent: string[];
};

export type Severity = "warning" | "failure";

export type HealthFinding = {
  severity: Severity;
  kind: "status" | "critical-error" | "console-error" | "failed-request" | "mixed-content";
  detail: string;
};

export class HealthFormatError extends Error {
  constructor(field: string, detail: string) {
    super(`health: ${field}: ${detail}`);
    this.name = "HealthFormatError";
  }
}

export const CRITICAL_ERROR_PHRASE = "There has been a critical error on this website";

type FailedRequest = HealthSnapshot["failedRequests"][number];
const requestKey = (r: FailedRequest) => `${r.status ?? ""} ${r.url}`;
const sortedUnique = (xs: string[]) => [...new Set(xs)].sort();

/** Deduplicates and deterministically sorts every list, keeping query strings and statuses distinct. */
export function normalizeHealth(h: HealthSnapshot): HealthSnapshot {
  const requests = new Map(h.failedRequests.map((r) => [JSON.stringify([r.url, r.status]), { url: r.url, status: r.status }]));
  return {
    status: h.status,
    finalUrl: h.finalUrl,
    criticalError: h.criticalError,
    consoleErrors: sortedUnique(h.consoleErrors),
    failedRequests: [...requests.values()].sort((a, b) =>
      a.url < b.url ? -1 : a.url > b.url ? 1 : (a.status ?? -1) - (b.status ?? -1),
    ),
    mixedContent: sortedUnique(h.mixedContent),
  };
}

/**
 * Findings for `actual`, relative to an optional baseline. HTTP >= 400, critical errors and mixed
 * content always fail. Console errors and failed URL/status pairs already in the baseline are
 * warnings; new ones fail; ones only in the baseline are not reported.
 */
export function evaluateHealth(actual: HealthSnapshot, baseline: HealthSnapshot | null): HealthFinding[] {
  const findings: HealthFinding[] = [];
  const fail = (kind: HealthFinding["kind"], detail: string) => findings.push({ severity: "failure", kind, detail });
  const known = (seen: boolean): Severity => (seen ? "warning" : "failure");

  if (actual.status === null) fail("status", `no HTTP response for ${actual.finalUrl}`);
  else if (actual.status >= 400) fail("status", `HTTP ${actual.status} for ${actual.finalUrl}`);
  if (actual.criticalError) fail("critical-error", `page shows "${CRITICAL_ERROR_PHRASE}"`);
  for (const url of sortedUnique(actual.mixedContent)) fail("mixed-content", `insecure resource ${url}`);

  const oldConsole = new Set(baseline?.consoleErrors);
  for (const message of sortedUnique(actual.consoleErrors)) {
    findings.push({ severity: known(oldConsole.has(message)), kind: "console-error", detail: message });
  }
  const oldRequests = new Set(baseline?.failedRequests.map(requestKey));
  for (const r of normalizeHealth(actual).failedRequests) {
    const what = r.status === null ? "transport failure" : `HTTP ${r.status}`;
    findings.push({ severity: known(oldRequests.has(requestKey(r))), kind: "failed-request", detail: `${what} ${r.url}` });
  }
  return findings;
}

/** Validates parsed `.health.json` content; throws `HealthFormatError` naming the bad field. */
export function parseHealth(value: unknown): HealthSnapshot {
  const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
  const isStatus = (v: unknown) => v === null || Number.isInteger(v);
  const strings = (v: unknown) => Array.isArray(v) && v.every((s) => typeof s === "string");
  if (!isObj(value)) throw new HealthFormatError("<root>", "must be an object");

  const keys = ["status", "finalUrl", "criticalError", "consoleErrors", "failedRequests", "mixedContent"];
  for (const key of Object.keys(value)) if (!keys.includes(key)) throw new HealthFormatError(key, "unknown key");
  const { status, finalUrl, criticalError, consoleErrors, failedRequests, mixedContent } = value;
  if (!isStatus(status)) throw new HealthFormatError("status", "must be an integer or null");
  if (typeof finalUrl !== "string") throw new HealthFormatError("finalUrl", "must be a string");
  if (typeof criticalError !== "boolean") throw new HealthFormatError("criticalError", "must be a boolean");
  if (!strings(consoleErrors)) throw new HealthFormatError("consoleErrors", "must be a list of strings");
  const requestOk = (r: unknown) => isObj(r) && Object.keys(r).length === 2 && typeof r.url === "string" && isStatus(r.status);
  if (!Array.isArray(failedRequests) || !failedRequests.every(requestOk)) {
    throw new HealthFormatError("failedRequests", "must be a list of {url, status}");
  }
  if (!strings(mixedContent)) throw new HealthFormatError("mixedContent", "must be a list of strings");
  return normalizeHealth(value as HealthSnapshot);
}

# Ponytail, lazy senior dev mode

You are a lazy senior developer. Lazy means efficient, not careless. The best code is the code never written.

Before writing any code, stop at the first rung that holds:

1. Does this need to be built at all? (YAGNI)
2. Does it already exist in this codebase? Reuse the helper, util, or pattern that's already here, don't re-write it.
3. Does the standard library already do this? Use it.
4. Does a native platform feature cover it? Use it.
5. Does an already-installed dependency solve it? Use it.
6. Can this be one line? Make it one line.
7. Only then: write the minimum code that works.

The ladder runs after you understand the problem, not instead of it: read the task and the code it touches, trace the real flow end to end, then climb.

Bug fix = root cause, not symptom: a report names a symptom. Grep every caller of the function you touch and fix the shared function once — one guard there is a smaller diff than one per caller, and patching only the path the ticket names leaves a sibling caller still broken.

Rules:

- No abstractions that weren't explicitly requested.
- No new dependency if it can be avoided.
- No boilerplate nobody asked for.
- Deletion over addition. Boring over clever. Fewest files possible.
- Shortest working diff wins, but only once you understand the problem. The smallest change in the wrong place isn't lazy, it's a second bug.
- Question complex requests: "Do you actually need X, or does Y cover it?"
- Pick the edge-case-correct option when two stdlib approaches are the same size, lazy means less code, not the flimsier algorithm.
- Mark deliberate simplifications that cut a real corner with a known ceiling (global lock, O(n²) scan, naive heuristic) with a `ponytail:` comment naming the ceiling and upgrade path.

Not lazy about: understanding the problem (read it fully and trace the real flow before picking a rung, a small diff you don't understand is just laziness dressed up as efficiency), input validation at trust boundaries, error handling that prevents data loss, security, accessibility, the calibration real hardware needs (the platform is never the spec ideal, a clock drifts, a sensor reads off), anything explicitly requested. Lazy code without its check is unfinished: non-trivial logic leaves ONE runnable check behind, the smallest thing that fails if the logic breaks (an assert-based demo/self-check or one small test file; no frameworks, no fixtures). Trivial one-liners need no test.

(Yes, this file also applies to agents working on the ponytail repo itself. Especially to them.)
# Pirax Castrum Maintenance

Visual and health checks for a hand-maintained list of WordPress sites, run from the operator's machine.

This repository currently contains the **foundation** only:

- the site list format and its loader (`src/sites.ts`),
- on-demand R2 configuration (`src/env.ts`),
- the R2 storage layer with report retention (`src/store.ts`),
- a selftest that exercises the storage layer against the real bucket.

There are no baseline, check or approve commands yet, and no browser code. Later work builds those on top of these modules.

## Setup

Requires [Bun](https://bun.sh) 1.4 or newer.

```sh
bun install
cp -n sites.example.yaml sites.yaml   # only creates sites.yaml if missing; then list your real sites
```

Create `.env` in the repository root with the four names from `.env.example`:

| Variable | Value |
| --- | --- |
| `S3_ACCESS_KEY_ID` | Cloudflare dashboard → R2 → Manage API tokens → create an **Object Read & Write** token scoped to the bucket. |
| `S3_SECRET_ACCESS_KEY` | The secret of that token. |
| `S3_ENDPOINT` | `https://<account-id>.r2.cloudflarestorage.com`, using the account ID from the R2 overview page. |
| `S3_BUCKET` | The exact name of the bucket you created. |

`.env` is gitignored. `.env.example` lists the names with empty values and is committed. Never commit real values or paste them into issues or logs.

## Commands

| Command | What it does | Needs R2 |
| --- | --- | --- |
| `bun test` | Unit tests for the site loader, env reader, store validation and retention selection, the selftest's missing-configuration path, and test discovery. `bunfig.toml` excludes `issues/**`, so leaf worktrees under `issues/worktrees/` are never picked up (Bun's discovery ignores `.gitignore`). | No |
| `bun run typecheck` | `tsc --noEmit` over `src`, `scripts` and `tests`. | No |
| `bun run store:selftest` | Real-bucket storage test (see [Storage selftest](#storage-selftest)). Runs `bun --env-file=.env scripts/store-selftest.ts`. | Yes |

## Site list

`sites.yaml` is operator-owned and committed; it holds no secrets. The tool never discovers pages: you list each page you want checked. A useful sample is the home page, one page per template or post type, and every page with a form.

```yaml
sites:
  - slug: acme                 # lowercase letters/digits, single internal hyphens, unique
    url: https://acme.example.com  # http(s), absolute, no trailing slash
    form_helper: false         # required; true once pirax-form-test is installed and configured on this site
    mask: ['#hero-slider']     # optional, CSS selectors masked on every page (default [])
    max_diff_pixel_ratio: 0.01 # optional, 0–1 (default 0.01)
    pages:                     # required, nonempty; order preserved
      - /
      - /services/
      - path: /contact/
        mask: ['.cookie-banner']   # optional, per page
```

`sites: []` is allowed. Unknown keys at any level are rejected.

`loadSites(path = "sites.yaml"): Site[]` reads the file synchronously and returns:

```ts
type Page = { path: string; mask: string[] };
type Site = { slug: string; url: string; form_helper: boolean; mask: string[]; max_diff_pixel_ratio: number; pages: Page[] };
```

Site and page masks stay separate; consumers combine them.

### Errors

Any problem throws `SitesConfigError` with `.site` and `.field`, and a message `"<file>: <site>: <field>: <detail>"`, for example:

```text
sites.yaml: acme: url: must not end with "/"
```

`site` is the slug, or `site[<index>]` when the slug is missing or invalid, or `<root>` for file-level problems. `field` is the failing part, such as `url`, `mask[1]`, `pages[2].path` or `pages[0].mask[0]`. Read errors report only the error code, and YAML errors report only the parser message, never file contents.

Page paths must start with a single `/` and must not contain a query, fragment, `.`/`..` segments (including `%2e` forms) or empty segments. Backslashes, spaces, tabs, newlines and other ASCII control characters are rejected too, because URL parsing turns `\` into `/` and drops tabs, newlines and trailing spaces, which could hide an off-site `//host` or a `..`. Percent-encode such characters instead, for example `/a%20b/`. A trailing slash is kept as written.

### Page keys and collisions

`pageKey(path)` turns a page path into the filename used in storage: `/` → `home`, `/a/b/` → `a-b`. Leading and trailing slashes are dropped, segments are joined with `-`, and characters outside `A-Z a-z 0-9 . _ -` are written as uppercase `%XX` UTF-8 bytes.

This readable format can map two paths to the same key. Within a site, these are rejected at load time (case-insensitively), rather than letting one baseline overwrite another:

- `/` and `/home/`
- `/a/b/` and `/a-b/`
- `/a` and `/a/`
- `/About/` and `/about/`

Duplicate paths are rejected too. Rename or drop one of the pages to fix it.

## Storage

Baselines and reports live in Cloudflare R2, accessed through Bun's built-in `S3Client`. Fixed layout:

```text
baselines/<slug>/<viewport>/<pageKey>.png
baselines/<slug>/<viewport>/<pageKey>.health.json
reports/<runId>/...
```

`runId` is `new Date().toISOString().replaceAll(":", "-")`, for example `2026-09-25T13-45-07.123Z`, so names sort chronologically.

### API

```ts
import { store, createStore, StoreError } from "./src/store.ts";

type Store = {
  put(key: string, data: Uint8Array | Blob): Promise<void>;  // Blob includes Bun.file(...)
  get(key: string): Promise<Uint8Array>;                     // rejects if the object is missing
  list(prefix: string): Promise<string[]>;                   // all pages, sorted, relative to the root
  presign(key: string, seconds: number): string;             // signed GET URL, 1–604800 whole seconds
  delete(key: string): Promise<void>;
  pruneReports(keep?: number): Promise<void>;                // default 10
};

createStore(options?: {
  config?: R2Config;  // default readR2Config(), read on first use
  root?: string;      // "" (default) or a prefix ending in "/"; keys are relative to it
  pageSize?: number;  // keys per list request, 1–1000; default is the service maximum
}): Store;
```

`store` is `createStore()`: the whole bucket, with credentials read on first use. Importing any module needs no environment. On first use, missing or blank variables throw `EnvError`, whose `.missing` and message list every missing name and no values.

Keys and roots are checked before any request. Invalid ones throw `StoreError`: empty keys, leading, trailing or doubled `/`, `.` or `..` segments, backslashes, control characters, or root plus key longer than 1024 bytes. `list` accepts `""` or a safe prefix with an optional trailing `/`. Signed URL expiry, `keep` and `pageSize` are validated the same way.

### Report retention

`pruneReports(keep = 10)` lists everything under `reports/`, groups objects by run directory, keeps the `keep` newest run directories and deletes every object in the older ones. It only touches directories whose name is a canonical run ID. It ignores:

- objects directly under `reports/`,
- directories with malformed or noncanonical names (for example without milliseconds, with colons, or with an impossible date),
- neighbouring prefixes such as `reports-old/`,
- `baselines/`.

`keep` must be a nonnegative integer. `0` removes all recognised report runs. With `keep` runs or fewer, nothing is deleted. Any list or delete error rejects the call, so a partial prune is never reported as success. Run it after a report run has finished: concurrent writers and pruners are not coordinated.

## Storage selftest

`bun run store:selftest` checks `src/store.ts` against the real bucket with the same code production uses. No mocks are involved.

What it writes: everything goes under a fresh root, `test/<timestamp>-<random>/`, which is printed at the start. Nothing outside that root is created, changed or deleted. Real `baselines/` and `reports/` are never touched.

What it checks, in order:

1. Bytes and `Bun.file` uploads round-trip unchanged.
2. `list` returns exactly the uploaded keys.
3. A 60-second signed GET URL, fetched over HTTP, returns the same bytes. Invalid expiries are rejected.
4. `get` of a missing key rejects.
5. With a list page size of 5, the service returns truncated pages. The paged listing of all 46 objects matches the unpaged one.
6. Invalid `keep` values reject and delete nothing.
7. 12 report runs of 3 objects each are pruned to 10. The two oldest runs are gone. Every surviving object keeps its original bytes, and the sentinels survive: baselines, a direct `reports/` object, malformed run directories and neighbouring prefixes.
8. Pruning again, and pruning with `keep` 50, changes nothing.
9. After adding two newer runs, `pruneReports()` keeps 10.
10. `keep` 0 removes every run and leaves the sentinels.

All retention runs use the page-size-5 store, so they cross list page boundaries.

Cleanup: in `finally`, whether or not a check failed, the selftest deletes every object under the test root, confirms the root lists empty, and removes its local temp directory. A cleanup failure makes the command fail and names only the test root.

Exit codes:

- `0`: all checks passed and cleanup succeeded.
- `1`: a check or the cleanup failed.
- `2`: required variables are missing or blank. These are named, no remote access is attempted, and no artifact is written.

Artifact: each run that reaches R2 writes `runs/store-selftest-<timestamp>.json` and prints its path. It records the command, start and finish times, the test root, `result` (`pass`/`fail`), each check with its counts or a sanitised error, and `cleanup` (`ok`, `deleted`, `remaining`, `error`). `runs/` is gitignored.

Output and artifacts never contain credentials, the endpoint, the bucket name, signed URLs or raw error messages. Errors the selftest does not author are reduced to their class and code, for example `S3Error (NoSuchKey)`.

## Limitations

- Masks are checked only as nonblank strings. Whether a selector is valid CSS or matches the page is not checked, because that needs a browser.
- The readable page-key format can collide. Collisions are rejected, not resolved.
- Retention is not transactional. Prune only when no report run is in progress.
- A folder-marker object such as `reports/<runId>/`, created outside this library, makes `pruneReports` reject with `StoreError` once its run expires. Bun's S3 client strips the trailing `/`, so it cannot address that exact key and would hit `reports/<runId>` instead. The marker is neither deleted nor skipped. Remove such markers with the tool that created them; this library never creates them.
- `pruneReports` deletes objects one request at a time. This is fine for tens of runs; very large reports will be slow.
- The selftest proves behaviour for the configured bucket and token. It does not check token scope beyond what it exercises, such as whether the token can also reach other buckets.
- If cleanup itself fails (for example the network drops), objects may remain under the printed `test/...` root. Delete that prefix by hand.
// Real-R2 selftest of src/store.ts. Every mutation stays under a fresh test/<timestamp>-<random>/ root,
// which is deleted in `finally`. Output and the runs/ artifact carry names, counts and error classes only:
// never credentials, endpoint, bucket, signed URLs or raw error messages.
import { S3Client } from "bun";
import { mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { EnvError, readR2Config, type R2Config } from "../src/env.ts";
import { createStore, StoreError } from "../src/store.ts";

class Failure extends Error {}

const assert = (ok: boolean, message: string) => {
  if (!ok) throw new Failure(message);
};
const same = (a: Uint8Array, b: Uint8Array) => a.length === b.length && a.every((v, i) => v === b[i]);
const sameList = (a: string[], b: string[]) => a.length === b.length && a.every((v, i) => v === b[i]);

// Only messages this script or the store authored are printed; anything else is reduced to its class/code.
function safe(e: unknown): string {
  if (e instanceof Failure || e instanceof StoreError || e instanceof EnvError) return e.message;
  const name = e instanceof Error ? e.name : typeof e;
  const code = (e as { code?: unknown })?.code;
  return typeof code === "string" && /^[A-Za-z0-9_]{1,64}$/.test(code) ? `${name} (${code})` : name;
}

let config: R2Config;
try {
  config = readR2Config();
} catch (e) {
  console.error(`store:selftest: ${safe(e)}. No remote access attempted.`);
  process.exit(2);
}

const PAGE = 5;
const started = new Date();
const stamp = started.toISOString().replaceAll(":", "-");
const root = `test/${stamp}-${crypto.randomUUID().slice(0, 8)}/`;
const store = createStore({ config, root });
const paged = createStore({ config, root, pageSize: PAGE });
const tmp = mkdtempSync(join(tmpdir(), "store-selftest-"));

type Check = { name: string; ok: boolean; counts?: Record<string, number>; error?: string };
const checks: Check[] = [];
async function check(name: string, fn: () => Promise<Record<string, number> | void>) {
  try {
    const counts = (await fn()) ?? undefined;
    checks.push({ name, ok: true, counts });
    console.log(`ok   ${name}${counts ? " " + JSON.stringify(counts) : ""}`);
  } catch (e) {
    checks.push({ name, ok: false, error: safe(e) });
    console.log(`FAIL ${name}: ${safe(e)}`);
    throw e;
  }
}
const rejects = async (p: Promise<unknown>) => {
  try {
    await p;
    return false;
  } catch {
    return true;
  }
};

const bytes = (n: number, seed: number) => Uint8Array.from({ length: n }, (_, i) => (i * 31 + seed) % 256);
const runId = (i: number) => new Date(Date.UTC(2026, 0, 1, 0, 0, i)).toISOString().replaceAll(":", "-");
const runFiles = ["summary.json", "acme/desktop/home.png", "acme/mobile/home.png"];
const expected = new Map<string, Uint8Array>();
async function putAll(keys: string[]) {
  for (const key of keys) {
    const data = bytes(64 + expected.size, expected.size);
    expected.set(key, data);
    await store.put(key, data);
  }
}
const runKeys = (from: number, to: number) =>
  Array.from({ length: to - from }, (_, i) => runFiles.map((f) => `reports/${runId(from + i)}/${f}`)).flat();
const sentinels = [
  "baselines/acme/desktop/home.png",
  "baselines/acme/desktop/home.health.json",
  "reports/index.html",
  "reports/not-a-run/x.json",
  "reports/2026-01-01T00-00-00Z/x.json",
  "reports/2026-02-30T00-00-00.000Z/x.json",
  "reports-old/2020-01-01T00-00-00.000Z/x.json",
  "other/reports/2020-01-01T00-00-00.000Z/x.json",
];
// Asserts the listing is exactly `keys` and every object still holds its uploaded bytes.
async function expectExactly(keys: string[]) {
  const all = await paged.list("");
  const want = [...keys].sort();
  assert(sameList(all, want), `expected ${want.length} objects under root, found ${all.length} (or different keys)`);
  for (const key of want) assert(same(await store.get(key), expected.get(key)!), `bytes changed for ${key}`);
  return all.length;
}

let passed = false;
let cleanup: { ok: boolean; deleted: number; remaining: number | null; error?: string } = { ok: false, deleted: 0, remaining: null };
console.log(`store:selftest root ${root}`);
try {
  await check("binary roundtrip", async () => {
    await putAll(["probe/bytes.bin"]);
    assert(same(await store.get("probe/bytes.bin"), expected.get("probe/bytes.bin")!), "downloaded bytes differ");
    return { bytes: expected.get("probe/bytes.bin")!.length };
  });

  await check("file roundtrip", async () => {
    const data = Uint8Array.from({ length: 256 }, (_, i) => 255 - i);
    const path = join(tmp, "upload.bin");
    await Bun.write(path, data);
    await store.put("probe/file.bin", Bun.file(path));
    expected.set("probe/file.bin", data);
    assert(same(await store.get("probe/file.bin"), data), "downloaded bytes differ");
    return { bytes: data.length };
  });

  await check("list", async () => {
    const keys = await store.list("probe/");
    assert(sameList(keys, ["probe/bytes.bin", "probe/file.bin"]), "probe listing differs");
    return { keys: keys.length };
  });

  await check("signed GET", async () => {
    const res = await fetch(store.presign("probe/bytes.bin", 60));
    assert(res.status === 200, `signed GET returned HTTP ${res.status}`);
    assert(same(new Uint8Array(await res.arrayBuffer()), expected.get("probe/bytes.bin")!), "signed GET bytes differ");
    let invalid = 0;
    for (const s of [0, -1, 1.5, Number.NaN, 604801])
      if (await rejects((async () => store.presign("probe/bytes.bin", s))())) invalid++;
    assert(invalid === 5, "invalid presign expiry accepted");

